{
  "items": [
    {
      "name": "nnnorm_sum_le",
      "module_name": "Mathlib.Analysis.Normed.Group.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_3} {E : Type u_5} [inst : SeminormedAddCommGroup E] (s : Finset ι) (f : ι → E),\n  ‖∑ a ∈ s, f a‖₊ ≤ ∑ a ∈ s, ‖f a‖₊"
    },
    {
      "name": "norm_sum_le",
      "module_name": "Mathlib.Analysis.Normed.Group.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_3} {E : Type u_9} [inst : SeminormedAddCommGroup E] (s : Finset ι) (f : ι → E),\n  ‖∑ i ∈ s, f i‖ ≤ ∑ i ∈ s, ‖f i‖"
    },
    {
      "name": "nat_abs_sum_le",
      "module_name": "Mathlib.Algebra.BigOperators.Group.Finset.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} (s : Finset ι) (f : ι → ℤ), (∑ i ∈ s, f i).natAbs ≤ ∑ i ∈ s, (f i).natAbs"
    },
    {
      "name": "Real.Lp_add_le",
      "module_name": "Mathlib.Analysis.MeanInequalities",
      "kind": "theorem",
      "type": "∀ {ι : Type u} (s : Finset ι) (f g : ι → ℝ) {p : ℝ},\n  1 ≤ p → (∑ i ∈ s, |f i + g i| ^ p) ^ (1 / p) ≤ (∑ i ∈ s, |f i| ^ p) ^ (1 / p) + (∑ i ∈ s, |g i| ^ p) ^ (1 / p)"
    },
    {
      "name": "MeasureTheory.eLpNorm'_sum_le",
      "module_name": "Mathlib.MeasureTheory.Function.LpSeminorm.TriangleInequality",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {ε' : Type u_4} {m : MeasurableSpace α} [inst : TopologicalSpace ε']\n  [inst_1 : ESeminormedAddCommMonoid ε'] {q : ℝ} {μ : MeasureTheory.Measure α} [ContinuousAdd ε'] {ι : Type u_5}\n  {f : ι → α → ε'} {s : Finset ι},\n  (∀ i ∈ s, MeasureTheory.AEStronglyMeasurable (f i) μ) →\n    1 ≤ q → MeasureTheory.eLpNorm' (∑ i ∈ s, f i) q μ ≤ ∑ i ∈ s, MeasureTheory.eLpNorm' (f i) q μ"
    },
    {
      "name": "nnnorm_tsum_le",
      "module_name": "Mathlib.Analysis.Normed.Group.InfiniteSum",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {E : Type u_3} [inst : SeminormedAddCommGroup E] {f : ι → E},\n  (Summable fun i => ‖f i‖₊) → ‖∑' (i : ι), f i‖₊ ≤ ∑' (i : ι), ‖f i‖₊"
    },
    {
      "name": "MeasureTheory.eLpNorm_sum_le",
      "module_name": "Mathlib.MeasureTheory.Function.LpSeminorm.TriangleInequality",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {ε' : Type u_4} {m : MeasurableSpace α} [inst : TopologicalSpace ε']\n  [inst_1 : ESeminormedAddCommMonoid ε'] {p : ENNReal} {μ : MeasureTheory.Measure α} [ContinuousAdd ε'] {ι : Type u_5}\n  {f : ι → α → ε'} {s : Finset ι},\n  (∀ i ∈ s, MeasureTheory.AEStronglyMeasurable (f i) μ) →\n    1 ≤ p → MeasureTheory.eLpNorm (∑ i ∈ s, f i) p μ ≤ ∑ i ∈ s, MeasureTheory.eLpNorm (f i) p μ"
    },
    {
      "name": "nnnorm_multiset_sum_le",
      "module_name": "Mathlib.Analysis.Normed.Group.Basic",
      "kind": "theorem",
      "type": "∀ {E : Type u_5} [inst : SeminormedAddCommGroup E] (m : Multiset E), ‖m.sum‖₊ ≤ (Multiset.map (fun x => ‖x‖₊) m).sum"
    }
  ]
}
